"""Two optional original investigations with real preparation and branching outcomes."""
def build_signature_affairs(rules):
 skills={s['id']:s for s in rules['skills']};definitions=[];english={}
 def event(id,title,title_en,brief,brief_en,location,stages):
  d={'schema_version':1,'id':id,'version':'1.0','package_id':'sui-guan-realms','package_version':'1','kind':'errand','title':title,'brief':brief,'public_location_ids':['sg-l%02d'%location],'objectives':[],'rewards':[],'choices':[]}
  en={'title':title_en,'brief':brief_en,'objectives':{},'choices':{}}
  prior=[]
  for index,(label,label_en,choices) in enumerate(stages,1):
   obj=id+'.stage'+str(index);d['objectives'].append({'id':obj,'description':label,'evidence':[{'kind':'choice','ref_id':obj}]});en['objectives'][obj]=label_en
   for n,x in enumerate(choices,1):
    cid=obj+'.c'+str(n);skill=skills['sg-'+x['skill']];loc=x.get('location',location)
    c={'id':cid,'title':x['title'],'description':x['description'],'objective_id':obj,'location_ids':['sg-l%02d'%loc],'after_objectives':prior[:],'skill_id':skill['id'],'required_skill':skill['id'],'required_skill_rank':1,'difficulty':x.get('difficulty',2),'duration_seconds':x.get('duration',3600),'rewards':[{'kind':'experience','ref_id':'experience','quantity':10}],'success':x['success'],'failure':x.get('failure','你停在还不能确认的地方，没有把缺失的依据写成既成结果。'),'echo_after_seconds':21600,'success_echo':x['echo'],'failure_echo':'这一步仍未走通，当事人继续自己的安排，愿不愿再谈要看后来的行动。','success_reaction':{'character_source_key':x.get('person','sg-p%02d'%loc),'statement':x['echo']},'failure_reaction':{'character_source_key':x.get('person','sg-p%02d'%loc),'statement':'这一步仍未走通，当事人继续自己的安排，愿不愿再谈要看后来的行动。'}}
    if skill['kind'] in ['social','engineering','repair','pilot']:c['use_skill_id']=skill['id']
    if skill.get('required_tool'):c['required_items']={skill['required_tool']:1}
    for key in ['item_costs','required_victory','required_items','required_character_source_keys','item_handovers']:
     if key in x:c[key]=x[key]
    if x.get('item'):c['rewards'].append({'kind':'item','ref_id':x['item'],'quantity':1})
    if x.get('pay'):c['rewards'].append({'kind':'currency','ref_id':rules['currency'],'quantity':x['pay']})
    d['choices'].append(c);en['choices'][cid]={'title':x['title_en'],'description':x['description_en'],'success':x['success_en'],'failure':'You stop where the evidence fails, without turning a missing fact into an accomplished result.','success_echo':x['echo_en'],'failure_echo':'This step remains unresolved. The people involved continue their own plans; later actions determine whether they will talk again.','success_reaction':x['echo_en'],'failure_reaction':'This step remains unresolved. The people involved continue their own plans; later actions determine whether they will talk again.'}
   prior.append(obj)
  definitions.append(d);english[id]=en
